doc=App.getDocument("hook_lesson5")
for o in doc.Objects:
    print(o.Name,o.Label,o.TypeId)
    if o.TypeId=="Spreadsheet::Sheet":
        for c in sorted(o.getUsedCells()):
            print("  ",c,o.getContents(c),o.getAlias(c))
    if hasattr(o,"ExpressionEngine") and o.ExpressionEngine: print("  expr",o.ExpressionEngine)
    if o.TypeId=="Sketcher::SketchObject":
        print("  geo",[str(g) for g in o.Geometry])
        for i,c in enumerate(o.Constraints): print("  c",i,c)
        print("  placement",o.Placement,o.Support if hasattr(o,'Support') else '')
    for p in ("Length","Type","Reversed","Midplane","Radius","Size","Profile","Base"):
        if hasattr(o,p): print("  ",p,getattr(o,p))

